<?php
// Run only in disposable checkout, with unshare -n. DB contains synthetic data only.
$base=dirname(__DIR__,3).'/linkstack';
if (!str_starts_with(realpath($base),'/tmp/linkfree-audit/')) throw new RuntimeException('Isolated path required');
chdir($base);require 'vendor/autoload.php';$app=require 'bootstrap/app.php';
$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Auth;use Illuminate\Http\Request;use App\Models\User;use App\Services\ReferralService as Ref;use App\Http\Controllers\VerificationController as VC;use App\Http\Controllers\AbuseReportController as RC;
if(config('database.connections.sqlite.database')!==$base.'/database/audit.sqlite')throw new RuntimeException('Unsafe database');
config(['session.driver'=>'array','cache.default'=>'array','mail.default'=>'array','mail.mailers.array'=>['transport'=>'array'],'linkstack.disable_random_user_ids'=>'true']);
$session=app('session')->driver();$session->start();
$results=[];
function check($id,$name,$fn){global $results;try{$fn();$results[]=['id'=>$id,'assertion'=>$name,'pass'=>true];echo "PASS $id $name\n";}catch(Throwable $e){$results[]=['id'=>$id,'assertion'=>$name,'pass'=>false,'error'=>$e->getMessage()];echo "FAIL $id $name: ".$e->getMessage()."\n";}}
function ok($v,$m='assertion failed'){if(!$v)throw new RuntimeException($m);}
function req($data=[],$url='/audit',$method='POST'){global $session;$r=Request::create('https://audit.example.test'.$url,$method,$data);$r->setLaravelSession($session);app()->instance('request',$r);return $r;}
function user($name,$role='user'){ $u=User::create(['name'=>$name,'email'=>$name.'@example.test','littlelink_name'=>$name,'password'=>bcrypt('Synthetic-password-123'),'email_verified_at'=>now()]);$u->role=$role;$u->save();return $u;}

$a=User::where('email','auditadmin@example.test')->firstOrFail();$u=User::where('email','auditfree@example.test')->firstOrFail();$v=User::where('email','auditvip@example.test')->firstOrFail();
check('TC-08-A','overquota and invalid import preserve existing links',function()use($u){Auth::login($u);$before=App\Models\Link::where('user_id',$u->id)->orderBy('id')->get()->toJson();$c=new App\Http\Controllers\UserController;foreach([array_fill(0,6,['type'=>'link']),[['type'=>'link','button_id'=>1,'link'=>'javascript:alert(1)','title'=>'invalid']]] as $links){$path=tempnam('/tmp','lf-import-');file_put_contents($path,json_encode(['links'=>$links]));$r=req();$r->files->set('import',new Illuminate\Http\UploadedFile($path,'synthetic.json','application/json',null,true));$c->importData($r);unlink($path);ok(App\Models\Link::where('user_id',$u->id)->orderBy('id')->get()->toJson()===$before);}});
check('TC-08-E','ordering persists and ignores foreign account link',function()use($u,$v){Auth::login($u);$own=App\Models\Link::where('user_id',$u->id)->pluck('id')->all();$foreign=App\Models\Link::where('user_id',$v->id)->first();$before=$foreign->order;$list=array_reverse($own);$list[]=$foreign->id;(new App\Http\Controllers\UserController)->sortLinks(req(['linkOrders'=>$list]));ok($foreign->fresh()->order===$before);ok(App\Models\Link::where('user_id',$u->id)->orderBy('order')->pluck('id')->all()===array_reverse($own));});
check('TC-05-D','database uniqueness enforced for codes and invited account',function()use($u){$c=DB::table('referral_codes')->where('user_id',$u->id)->first();try{DB::table('referral_codes')->insert(['user_id'=>$u->id,'code'=>$c->code]);throw new RuntimeException('duplicate accepted');}catch(Illuminate\Database\QueryException $e){}$r=DB::table('referrals')->first();try{DB::table('referrals')->insert(['referrer_user_id'=>$u->id,'invited_user_id'=>$r->invited_user_id,'referral_code'=>$c->code]);throw new RuntimeException('duplicate accepted');}catch(Illuminate\Database\QueryException $e){}ok(count(DB::select('pragma foreign_key_check'))===0);});
check('TC-04-B','duplicate email rejected and creation failure rolls back complete controller',function()use($session){$c=new App\Http\Controllers\Auth\RegisteredUserController;try{$c->store(req(['name'=>'Duplicate','email'=>'auditfree@example.test','littlelink_name'=>'duplicate','password'=>'Synthetic-password-123','accept_terms'=>1]));throw new RuntimeException('duplicate accepted');}catch(Illuminate\Validation\ValidationException $e){ok(isset($e->errors()['email']));}DB::statement("CREATE TRIGGER fail_consent BEFORE INSERT ON registration_consents BEGIN SELECT RAISE(ABORT, 'synthetic consent failure'); END");$before=User::count();try{$c->store(req(['name'=>'Failure','email'=>'failure@example.test','littlelink_name'=>'failure','password'=>'Synthetic-password-123','accept_terms'=>1]));throw new RuntimeException('failure not triggered');}catch(Illuminate\Database\QueryException $e){}finally{DB::statement('DROP TRIGGER fail_consent');}ok(User::count()===$before);ok(!User::where('email','failure@example.test')->exists());});
file_put_contents(dirname(__DIR__).'/evidencias/extension.json',json_encode($results,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));
